//! 🧪️ Genuine semantic borrows retain actual admitted native pages and the original caller receipt.
use semio_framework_job::*;
use semio_framework_value::ValueError;
use std::mem::size_of;
#[path="../../../🧪️testing/📬️payload/🦀️.rs"]
mod original_payload;
#[global_allocator]
static ORIGINAL_LOAN_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn delta(before:RetainedCloneProgress,after:RetainedCloneProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:after.copied_items.checked_sub(before.copied_items).unwrap(),copied_bytes:after.copied_bytes.checked_sub(before.copied_bytes).unwrap(),retained_capacity_bytes:after.retained_capacity_bytes.checked_sub(before.retained_capacity_bytes).unwrap(),released_bytes:after.released_bytes.checked_sub(before.released_bytes).unwrap()}}
struct OriginalLoanJob<'a>{payload:&'a mut RetainedPayloadBuilder,output:&'a RetainedJobPayload,kind:u8,closing:bool}
impl InteractiveJob for OriginalLoanJob<'_>{
 fn step<'a>(&'a mut self,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,OriginalTurnFailure>{let payload=self.payload.published().unwrap();match self.kind{0=>JobOutcomeBorrow::admit_yield(cx),1=>JobOutcomeBorrow::admit_preview(cx,payload),2=>JobOutcomeBorrow::admit_checkpoint(cx,payload,17),3=>JobOutcomeBorrow::admit_complete(cx,Some(payload),Some(self.output)),4=>JobOutcomeBorrow::admit_cancelled(cx),5=>JobOutcomeBorrow::admit_fault(cx,payload),_=>unreachable!()}.map_err(OriginalTurnFailure::from)}
 fn borrow_outcome<'a>(&'a self,original:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{let payload=self.payload.published().unwrap();match original.kind(){JobOutcomeKind::Yield=>original.yielded(),JobOutcomeKind::PreviewReady=>original.preview(payload),JobOutcomeKind::CheckpointReady{..}=>original.checkpoint(payload),JobOutcomeKind::Complete=>original.complete(Some(payload),Some(self.output)),JobOutcomeKind::Cancelled=>original.cancelled(),JobOutcomeKind::Fault=>original.fault(payload)}}
 fn begin_close(&mut self){self.closing=true;}
 fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{if cx.should_yield(){return Ok(InteractiveJobCloseStep::Pending{progress:Default::default()})}let before=cx.retained_progress();let complete=self.payload.close_step(cx)?;let progress=delta(before,cx.retained_progress());if progress!=Default::default(){cx.consume_fuel(1)}Ok(if complete{InteractiveJobCloseStep::Complete{progress}}else{InteractiveJobCloseStep::Pending{progress}})}
 fn terminal_is_empty(&self)->bool{self.closing&&self.payload.terminal_is_empty()&&self.output.terminal_is_empty()}
}
#[test]
fn original_semantic_outcome_loans_preserve_payload_identity_fixed_grants_and_current_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();assert_eq!(law["pageBytes"],JOB_PAYLOAD_PAGE_BYTES);let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};let demand=JobOutcomeBorrow::admission_demand();assert!(demand.copy_bytes<4096);assert!(size_of::<StepOutcome>()>4096);
 semio_framework_trace::record_trace_event_at(OperationId(99101),Generation(1),semio_framework_trace::TraceStage::Cancelled,Some(1));let(_,shared_trace)=original_payload::observe(||semio_framework_trace::Watchdog::start_at("job.original-semantic-loan",OperationId(99101),Generation(1),InteractiveStage::InteractiveStep,Some(1)).finish_at(Some(2)));assert_eq!(shared_trace.1,0);
 for (kind,variant)in law["variants"].as_array().unwrap().iter().enumerate(){for extent in law["pageExtents"].as_array().unwrap(){let extent=extent.as_u64().unwrap()as usize;for pages in law["pages"].as_array().unwrap(){let pages=pages.as_u64().unwrap()as usize;let bytes:Vec<u8>=(0..pages).flat_map(|index|std::iter::repeat_n(index as u8,extent)).collect();let mut prepared=original_payload::OriginalTestPayload::admit(OperationId(99101),Generation(1),JobPayloadStream::Preview,&bytes,extent);let before=prepared.caller.cumulative_receipt();let born=before.retained_capacity_bytes;let mut released=before.released_bytes;let output=RetainedJobPayload::empty(JobPayloadStream::CommitOutput);let mut job=OriginalLoanJob{payload:&mut prepared.builder,output:&output,kind:kind as u8,closing:false};let original=job.payload.published().unwrap();assert_eq!(original.page_count(),pages);for index in 0..pages{assert_eq!(original.page(index),Some(vec![index as u8;extent].as_slice()));assert_eq!(original.page_capacity_bytes(index),Some(extent));}let payload_pointer=original as*const RetainedJobPayload;let page_pointer=original.page(0).map(|page|page.as_ptr());
  for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(answer,heap)=original_payload::observe(||prepared.caller.turn(denied,|cx|{let before=cx.retained_progress();let mut verdict=None;let result=drive_step(&mut job,cx,"job.original-semantic-loan",InteractiveStage::InteractiveStep,&mut verdict).unwrap();assert!(result.is_none());assert_eq!(cx.retained_progress(),before);Ok(())}));answer.unwrap();assert_eq!(heap,(0,0));assert_eq!(prepared.caller.receipt(),Default::default());assert_eq!(job.payload.published().unwrap()as*const RetainedJobPayload,payload_pointer);assert_eq!(job.payload.published().unwrap().page(0).map(|page|page.as_ptr()),page_pointer);}
  let(answer,heap)=original_payload::observe(||prepared.caller.turn(grant,|cx|{let before=cx.retained_progress();let mut verdict=None;let outcome=drive_step(&mut job,cx,"job.original-semantic-loan",InteractiveStage::InteractiveStep,&mut verdict).unwrap().unwrap();assert_eq!(outcome.admission().progress(),delta(before,cx.retained_progress()));assert_eq!(delta(before,cx.retained_progress()),RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()});let original=match &outcome{JobOutcomeBorrow::PreviewReady{payload,..}=>Some(*payload),JobOutcomeBorrow::CheckpointReady{state,applied_progress,..}=>{assert_eq!(*applied_progress,17);Some(*state)},JobOutcomeBorrow::Complete{state,output,..}=>{assert!(output.unwrap().terminal_is_empty());*state},JobOutcomeBorrow::Fault{detail,..}=>Some(*detail),_=>None};if let Some(original)=original{assert!(std::ptr::eq(original,payload_pointer));assert_eq!(original.page(0).map(|page|page.as_ptr()),page_pointer);}assert!(verdict.is_some());Ok(())}));answer.unwrap();assert_eq!(heap,(0,0));assert_eq!(prepared.caller.receipt(),RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()});assert_eq!(job.payload.published().unwrap().page(0).map(|page|page.as_ptr()),page_pointer);
  job.begin_close();for turn in 0..4096{if job.terminal_is_empty(){break}let(answer,heap)=original_payload::observe(||prepared.caller.turn(grant,|cx|{let before=cx.retained_progress();let step=job.close_step(cx).unwrap();assert_eq!(step.progress(),delta(before,cx.retained_progress()));Ok(step)}));let step=answer.unwrap();assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.1;assert!(turn<4095);}assert!(job.terminal_is_empty());assert_eq!(original_payload::observe(||drop(job)).1,(0,0));
  for turn in 0..64{if prepared.caller.terminal_is_empty(){break}let(answer,heap)=original_payload::observe(||prepared.caller.retire_step(grant));let step=answer.unwrap();assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.1;assert!(turn<63);}assert!(prepared.caller.terminal_is_empty());assert_eq!(born,released);let receipt=prepared.caller.cumulative_receipt();assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),(born,released));assert_eq!(original_payload::observe(||{drop(prepared);drop(output)}).1,(0,0));
 }}}
}
